package com.example.domain.model.i18n

internal object DuaMs1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Ketika bangun tidur", "Segala puji bagi Allah yang telah menghidupkan kami setelah mematikan kami, dan kepada-Nya kami kembali.", "Dibaca sebaik sahaja bangun tidur sebagai tanda syukur kepada Allah.", "Nabi ﷺ membacanya ketika bangun tidur — memulakan hari dengan syukur dan mengingati akhirat."),
        "dua_leaving_home" to DuaText("Ketika keluar rumah", "Dengan nama Allah, aku bertawakal kepada Allah, tiada daya dan upaya melainkan dengan Allah.", "Dibaca ketika keluar rumah untuk memohon perlindungan.", "Kepada yang membacanya dikatakan: kamu telah diberi petunjuk, dicukupkan, dan dilindungi — lalu syaitan pun menjauhinya."),
        "dua_anxiety_distress" to DuaText("Doa kesedihan dan kerisauan", "Ya Allah, aku berlindung kepada-Mu daripada rasa sedih dan risau, daripada lemah dan malas, daripada bakhil dan penakut, daripada bebanan hutang dan tekanan manusia.", "Ketika sedih, risau, berhutang, dan gundah hati.", "Nabi ﷺ kerap membaca doa ini untuk berlindung daripada kesedihan, kemalasan, dan hutang."),
        "dua_sayyidul_istighfar" to DuaText("Penghulu istighfar (Sayyidul Istighfar)", "Ya Allah, Engkaulah Tuhanku, tiada tuhan melainkan Engkau. Engkau menciptakan aku dan aku adalah hamba-Mu. Aku berpegang pada janji-Mu semampu aku. Aku berlindung kepada-Mu daripada kejahatan yang telah kulakukan. Aku mengakui nikmat-Mu ke atasku dan aku mengakui dosaku, maka ampunilah aku, kerana tiada yang mengampunkan dosa melainkan Engkau.", "Dibaca pagi dan petang — doa taubat paling utama yang diajarkan Nabi ﷺ.", "Sesiapa membacanya pada waktu petang dengan penuh yakin lalu meninggal pada malam itu, dia masuk syurga; begitu juga jika dibaca pada waktu pagi."),
        "dua_parents" to DuaText("Doa untuk kedua ibu bapa", "Wahai Tuhanku, kasihanilah mereka berdua sebagaimana mereka telah mendidikku semasa kecil.", "Doa daripada Al-Quran sebagai balasan atas didikan ibu bapa sejak kecil.", "Allah memerintahkan doa ini untuk ibu bapa secara langsung di dalam Al-Quran."),
        "dua_entering_mosque" to DuaText("Ketika masuk masjid", "Ya Allah, bukakanlah untukku pintu-pintu rahmat-Mu.", "Dibaca ketika masuk masjid dengan kaki kanan.", "Nabi ﷺ mengajarkan doa ini ketika masuk masjid."),
        "dua_morning_asbahna" to DuaText("Zikir pagi", "Kami telah memasuki waktu pagi dan kerajaan ini kepunyaan Allah; segala puji bagi Allah; tiada tuhan melainkan Allah semata-mata, tiada sekutu bagi-Nya; kepunyaan-Nya kerajaan dan pujian, dan Dia Maha Berkuasa atas segala sesuatu.", "Zikir sunat yang dibaca pada waktu pagi.", "Memulakan hari dengan mengakui kekuasaan dan keesaan Allah."),
        "dua_evening_amsayna" to DuaText("Zikir petang", "Kami telah memasuki waktu petang dan kerajaan ini kepunyaan Allah; segala puji bagi Allah; tiada tuhan melainkan Allah semata-mata, tiada sekutu bagi-Nya; kepunyaan-Nya kerajaan dan pujian, dan Dia Maha Berkuasa atas segala sesuatu.", "Zikir sunat yang dibaca pada waktu petang.", "Memulakan malam dengan mengakui kekuasaan dan keesaan Allah."),
        "dua_before_sleep" to DuaText("Sebelum tidur", "Dengan nama-Mu ya Allah aku mati dan aku hidup.", "Dibaca selepas berbaring untuk tidur.", "Nabi ﷺ membacanya sebelum tidur."),
        "dua_travel" to DuaText("Doa perjalanan", "Maha Suci Tuhan yang telah menundukkan kenderaan ini untuk kami, padahal kami sebelum ini tidak mampu menguasainya; dan sesungguhnya kepada Tuhan kami, kami akan kembali.", "Dibaca semasa menaiki kenderaan selepas bertakbir tiga kali.", "Doa perjalanan yang disunatkan untuk perlindungan dan keberkatan."),
        "dua_ayatul_kursi" to DuaText("Ayat Kursi selepas solat", "Allah, tiada tuhan melainkan Dia, Yang Hidup, Yang Berdiri Sendiri mentadbirkan sekalian makhluk-Nya; tidak mengantuk dan tidak tidur; kepunyaan-Nya apa yang di langit dan di bumi; siapakah yang dapat memberi syafaat di sisi-Nya tanpa izin-Nya; Dia mengetahui apa yang di hadapan dan di belakang mereka; mereka pula tidak mengetahui sesuatu pun daripada ilmu Allah melainkan apa yang Allah kehendaki; Kursi-Nya meliputi langit dan bumi, dan Dia tidak berat memelihara keduanya; Dan Dialah Yang Maha Tinggi, lagi Maha Besar.", "Dibaca selepas setiap solat fardu dan sebelum tidur.", "Sesiapa membacanya selepas setiap solat fardu, tiada yang menghalangnya masuk syurga melainkan kematian; sesiapa membacanya sebelum tidur, dia dilindungi sehingga pagi."),
        "dua_hasbunallah" to DuaText("Cukuplah Allah bagi kami", "Cukuplah Allah bagi kami, dan Dialah sebaik-baik pelindung.", "Dibaca ketika takut akan musuh atau bahaya besar.", "Nabi Ibrahim mengucapkannya ketika dicampakkan ke dalam api, dan Nabi ﷺ mengucapkannya ketika menghadapi bahaya."),
        "dua_entering_home" to DuaText("Ketika masuk rumah", "Dengan nama Allah kami masuk, dengan nama Allah kami keluar, dan kepada Allah Tuhan kami, kami bertawakal.", "Dibaca ketika masuk rumah sambil menyebut nama Allah dan memberi salam.", "Kepada yang mengingati Allah ketika masuk rumah dan ketika makan, syaitan berkata: tiada tempat menginap dan tiada makan malam untuk kamu."),
        "dua_yunus" to DuaText("Doa Nabi Yunus alaihissalam", "Tiada tuhan melainkan Engkau, Maha Suci Engkau; sesungguhnya aku termasuk golongan yang zalim.", "Doa Nabi Yunus alaihissalam di dalam perut ikan — untuk segala kesusahan.", "Tidak seorang Muslim pun berdoa dengannya dalam sesuatu perkara melainkan Allah memperkenankannya."),
        "dua_karb" to DuaText("Doa ketika kesusahan yang berat", "Tiada tuhan melainkan Allah Yang Maha Agung lagi Maha Penyantun. Tiada tuhan melainkan Allah, Tuhan pemilik Arasy yang agung. Tiada tuhan melainkan Allah, Tuhan langit dan bumi serta Tuhan Arasy yang mulia.", "Dibaca ketika kesusahan dan kesempitan yang berat.", "Nabi ﷺ membacanya ketika berada dalam kesusahan."),
    )
}
